const item = $input.first();
const body = item.json.body ?? {};
const binary = item.binary ?? {};
const cv = binary.cv;

const reject = (code, reason) => [{
  json: { ...item.json, passed: false, rejectCode: code, rejectReason: reason },
  binary: item.binary,
}];

const honeypotFields = ['website', 'company_url', 'url', 'hp', 'honeypot', 'bot_field', 'fax'];
for (const field of honeypotFields) {
  const val = body[field];
  if (val !== undefined && val !== null && String(val).trim() !== '') {
    return reject('honeypot', `Honeypot field "${field}" was filled`);
  }
}

const fullName = String(body.full_name || '').trim();
if (!fullName || fullName.length < 2) {
  return reject('invalid_name', 'Full name is missing or too short');
}

const email = String(body.email || '').trim();
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!email || !emailRegex.test(email)) {
  return reject('invalid_email', 'Invalid or missing email address');
}

const phone = String(body.phone || '').trim();
if (!phone || phone.replace(/\D/g, '').length < 7) {
  return reject('invalid_phone', 'Invalid or missing phone number');
}

if (!body.campaignId) return reject('missing_campaign', 'Missing campaign ID');
if (!body.id) return reject('missing_candidate', 'Missing candidate ID');
if (!cv) return reject('missing_cv', 'CV file is required');

/* 2026-09-15 — PDF is no longer the only readable CV.
   The backend extracts the text itself (cvTextExtractor: pdf-parse, mammoth,
   plain read) and sends it as `body.cvText`, so DOCX and TXT are now genuinely
   readable end to end. This gate used to reject them here, before anything was
   read — the candidate never appeared on the board at all, and DOCX is the most
   common thing uploaded locally.
   Kept as a gate, not removed: an image or an executable still has no text layer
   and must not reach the assessor. Accepts by MIME or by extension, because some
   browsers send application/octet-stream for .docx. */
const mime = String(cv.mimeType || cv.fileType || '').toLowerCase();
const cvName = String(cv.fileName || cv.name || body.cv_filename || '').toLowerCase();
const ext = cvName.includes('.') ? cvName.split('.').pop() : '';
const hasBackendText = String(body.cvText || '').trim().length > 0;
const typeOk =
  hasBackendText ||
  mime.includes('pdf') ||
  mime.includes('wordprocessingml') ||
  mime.includes('msword') ||
  mime.includes('text/plain') ||
  ext === 'pdf' || ext === 'docx' || ext === 'txt';
if (!typeOk) {
  return reject('invalid_cv_type', 'CV must be a PDF, DOCX or TXT file');
}

const maxBytes = 5 * 1024 * 1024;
let sizeNum = cv.bytes ?? 0;
if (typeof cv.fileSize === 'string') {
  const match = cv.fileSize.match(/([\d.]+)\s*(kb|mb|gb)?/i);
  if (match) {
    const num = parseFloat(match[1]);
    const unit = (match[2] || '').toLowerCase();
    if (unit === 'gb') sizeNum = num * 1024 * 1024 * 1024;
    else if (unit === 'mb') sizeNum = num * 1024 * 1024;
    else if (unit === 'kb') sizeNum = num * 1024;
    else sizeNum = num;
  }
}
if (sizeNum > maxBytes) return reject('cv_too_large', 'CV exceeds the 5MB size limit');

if (body.skills) {
  try {
    const skills = typeof body.skills === 'string' ? JSON.parse(body.skills) : body.skills;
    if (!Array.isArray(skills)) throw new Error('not array');
  } catch {
    return reject('invalid_skills', 'Skills must be a valid JSON array');
  }
}

if (body.criteria) {
  try {
    const criteria = typeof body.criteria === 'string' ? JSON.parse(body.criteria) : body.criteria;
    if (!Array.isArray(criteria)) throw new Error('not array');
  } catch {
    return reject('invalid_criteria', 'Criteria must be a valid JSON array');
  }
}

return [{
  json: { ...item.json, passed: true, rejectCode: '', rejectReason: '' },
  binary: item.binary,
}];

const webhook = $('Webhook').first();
const preCheck = $('Spam Pre-Check').first();
const dupes = $('Find Duplicates').all().filter((item) => {
  const row = item.json || {};
  return row._id || row.CandidateID || row.ApplicantEmail || row.ApplicantPhone;
});

if (dupes.length > 0) {
  return [{
    json: {
      passed: false,
      rejectCode: 'duplicate',
      rejectReason: 'A candidate with this email or phone already applied to this campaign.',
      body: webhook.json.body,
    },
    binary: preCheck.binary,
  }];
}

return [{
  json: {
    passed: true,
    rejectCode: '',
    rejectReason: '',
    body: webhook.json.body,
  },
  binary: preCheck.binary,
}];

const items = $input.all();
return items.map((item) => {
  const body = item.json.body ?? {};
  const callbackUrl = String(body.callbackUrl || '').trim();
  const inboundSecret = String(body.inboundSecret || '').trim();
  const candidateId = String(body.candidateId || body.id || '').trim();
  const inputValid = Boolean(callbackUrl && inboundSecret && candidateId);
  return {
    ...item,
    json: {
      ...item.json,
      __evaaloStageSecurity: {
        ...(item.json.__evaaloStageSecurity ?? {}),
        inputValid,
      },
    },
  };
});

const items = $input.all();

function parseQuery(query) {
  const params = {};
  if (!query) return params;
  for (const part of String(query).split('&')) {
    if (!part) continue;
    const eq = part.indexOf('=');
    const key = eq >= 0 ? decodeURIComponent(part.slice(0, eq)) : decodeURIComponent(part);
    const val = eq >= 0 ? decodeURIComponent(part.slice(eq + 1)) : '';
    params[key] = val;
  }
  return params;
}

return items.map((item) => {
  const body = item.json.body ?? {};
  const callbackUrlRaw = String(body.callbackUrl || '').trim();

  const ALLOWED_ORIGINS = new Set([
    'https://api.evaalo.com',
    'http://100.73.82.78:5000',
  ]);
  const ALLOWED_PATHS = new Set([
    '/webhook/n8n/stage1',
    '/webhook/n8n/stage2',
    '/webhook/n8n/stage3',
    '/webhook/n8n/video',
  ]);
  const REQUIRED_KEYS = ['candidateId', 'mode', 'sessionId', 'campaignId', 'issuedAt', 'expiresAt', 'token'];
  const NON_EMPTY_KEYS = ['candidateId', 'mode', 'issuedAt', 'expiresAt', 'token'];

  let urlValid = false;
  if (callbackUrlRaw && !callbackUrlRaw.includes('@')) {
    const m = callbackUrlRaw.match(/^(https?):\/\/([^/:?#]+)(?::(\d+))?(\/[^?#]*)?(?:\?([^#]*))?/i);
    if (m) {
      const protocol = m[1].toLowerCase();
      const host = m[2];
      const port = m[3] || '';
      const pathname = m[4] || '/';
      const query = m[5] || '';
      const origin = port ? `${protocol}://${host}:${port}` : `${protocol}://${host}`;
      if (ALLOWED_ORIGINS.has(origin) && ALLOWED_PATHS.has(pathname)) {
        const params = parseQuery(query);
        urlValid = REQUIRED_KEYS.every((key) => Object.prototype.hasOwnProperty.call(params, key));
        if (urlValid) {
          urlValid = NON_EMPTY_KEYS.every((key) => String(params[key] ?? '').trim() !== '');
        }
        if (params.mode !== 'stage1') urlValid = false;
      }
    }
  }

  return {
    ...item,
    json: {
      ...item.json,
      __evaaloStageSecurity: {
        ...(item.json.__evaaloStageSecurity ?? {}),
        urlValid,
      },
    },
  };
});

const items = $input.all();
function parseJsonLoose(raw) {
  if (raw == null) return null;
  if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
  if (typeof raw !== 'string') return null;
  let s = raw.trim();
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const m = s.match(/\{[\s\S]*\}/);
  if (m) s = m[0];
  try { return JSON.parse(s); } catch { return null; }
}
function pickEval(item) {
  const validated = $('Stage 1 Scoring').first().json.evaluation;
  let o = parseJsonLoose(item.json.output ?? item.json.text ?? item.json);
  if (o && o.output && typeof o.output === 'object') o = o.output;
  if (!o || typeof o !== 'object') o = validated;
  const lang = String($('Webhook').first().json.body?.evaluationLanguage || 'ar').trim().toLowerCase();
  if (lang === 'en') return validated;
  const merged = { ...validated, ...o };
  return {
    overall_score: validated.overall_score,
    recommendation: validated.recommendation,
    strengths: merged.strengths,
    weaknesses: merged.weaknesses,
    red_flags: validated.red_flags ?? [],
    summary: merged.summary,
    fit_for_role: merged.fit_for_role,
    final_hr_evaluation: merged.final_hr_evaluation,
  };
}
return items.map((item) => ({ json: { valid: true, evaluation: pickEval(item) }, binary: item.binary }));

