const STATUS_FRACTION = { met: 1.0, partial: 0.5, missing: 0.0 };
// وزن كل معيار. كانت المعايير متساوية، فكان الجنسُ يساوي الوظيفةَ نفسها: مهندس
// بترول تقدّم لوظيفة مساعد موارد بشرية في بغداد ففشل في الوظيفة والموقع والقطاع،
// ونجح في الجنس والبكالوريوس ولقب «Senior» الذي كتبه بنفسه — فخرج بـ50% و«Consider»
// بينما السرد نفسه يقول «ليس مناسباً». الوزن يجعل ملاءمة الدور تحكم النتيجة.
// gender = 0 عمداً: يُسجَّل كشرط لصاحب العمل ولا يُحتسب جدارةً.
//
// 2026-09-15 — أربعة مفاتيح أُضيفت لأنها كانت تسقط على الوزن الافتراضي 8 بلا قرار:
//   age = 0 — يخالف القاعدة أعلاه حرفياً: عمر المرشح شرطٌ لصاحب العمل لا فضيلةٌ
//     فيه، ولا يملك المرشح تغييره. ورأيناه يعمل: مرشح بعمر 25 لوظيفة طلبت 18-24
//     خسر 8 نقاط كاملة. يُسجَّل ويُعرَض في التفصيل كما هو، ولا يدخل الحساب.
//   salarymin = 5، salarymax = salarycurrency = 0 — كانت الثلاثة تأخذ 8 لكل
//     واحد، فيصير شرط الراتب الواحد 24 نقطة أي بوزن الوظيفة نفسها (25). الراتب
//     الآن معيار واحد بوزن لوجستي، والحدّ الأعلى والعملة يُسجَّلان بلا نقاط.
// مجموع المفاتيح ذات الوزن صار 105 بعد إضافة الراتب (كان 100). الرقم مرجعي فقط:
// المقام دائماً هو مجموع أوزان ما اختاره صاحب العمل، لا هذا المجموع.
//
// 2026-09-15 (مساءً) — إعادة توزيع كاملة على 100 نقطة، وكل مفتاح جاهز له وزن صريح:
//   الخبرة ذات الصلة 25 (كانت 15) — البرومبت صار يحسبها من تاريخ العمل المؤرّخ في
//     السيرة في الوظيفة نفسها، لا من الرقم المكتوب ولا من مجموع سنوات أي عمل؛
//     المسمّى 20 (كان 25) — الترتيبُ للوزن، أمّا «هل يعمل في هذه الوظيفة أصلاً» فتحكمه
//     بوّابة الدور أدناه؛ المستوى الوظيفي 8 والمسار الإداري 2 (مفهوم واحد = 10)،
//     و«Job Level» المكتوب صفر لأنه تكرار للمستوى القادم من الكتالوج؛
//     التعليم 10؛ الشهادات 8 صراحةً (كانت 8 افتراضياً)؛ القطاع 5؛ اللغات 5؛ الموقع 2.
//   الراتب والتوفّر والشركة صفر: لوجستيات تُسجَّل ولا تُحتسب جدارة — ومن أرادها
//     حاسمة يعلّمها «شرط أساسي» (الشرط يعمل بوزن صفر أيضاً).
//   المجموع 100. الوزن الافتراضي 8 صار للمعايير المكتوبة يدوياً فقط.
//
// 2026-09-16 — الموقع 2 → 5 بعد مراجعة نقديّة: في 9 من 25 حملة يكون الموقع أحدَ
//   معيارين فقط يختارهما المُعيّن بنفسه (المستوى والمسار يأتيان من الكتالوج)، وكان
//   يمثّل 6.3% من درجتها فقط. صار 14.3%. مجموع المفاتيح ذات الوزن 103 الآن — رقم
//   مرجعيّ لا أكثر. التعليم لم يُمَسّ عمداً: حجّة «لنُبقِ المجموع 100» خاطئة حسابياً.
const CRITERION_WEIGHT = {
  position: 20,
  experienceyears: 25,
  skills: 15,
  careerlevel: 8,
  managementtrack: 2,
  educationlevel: 10,
  certifications: 8,
  industrytype: 5,
  languages: 5,
  location: 5,
  job: 0,
  company: 0,
  availability: 0,
  salarymin: 0,
  salarymax: 0,
  salarycurrency: 0,
  age: 0,
  gender: 0,
};
const DEFAULT_WEIGHT = 8; // معيار مخصّص كتبه صاحب العمل بنفسه — كل مفتاح جاهز له وزن صريح أعلاه، فلا يسقط شيء منها هنا
const COVERAGE_FLOOR = 0.5;
const T_ADVANCE = 70;
const T_CONSIDER = 49;
/* MUST-HAVES (2026-09-15). A recruiter screens in two passes: drop whoever misses
   the essentials, then rank the rest. Until now this node had only the second
   pass, so a candidate who failed the role outright could still reach Hire on the
   strength of everything else. The recruiter can now flag a criterion
   `essential: true`; one that is not confirmed as `met` caps the recommendation at
   ESSENTIAL_UNMET_CAP and routes the file to a human, the same way an integrity
   concern already does. `partial` and `not_assessed` count as not confirmed: a
   must-have that is merely claimed, or that the application says nothing about,
   is not a must-have you can advance on. Set the cap to 'Reject' to make an unmet
   essential a hard knockout instead. */
const ESSENTIAL_UNMET_CAP = 'Consider';
/* ROLE-FIT FLOOR (2026-09-15). The denominator is the sum of the weights the
   recruiter selected, so the share of the role-fit criteria swung with the number
   of other criteria ticked: position alone was 60% of a 4-criterion rubric and
   18% of a 16-criterion one, and a candidate who missed the role outright could
   still reach Hire on a broad rubric. A recruiter reads it the other way round:
   the job is the job, and the extras refine the ranking among people who fit it.
   The four role-fit keys below now hold at least CORE_FLOOR of the score whenever
   the selection would naturally give them less; a rubric where they already hold
   more (the usual 3- and 4-criterion rubrics) is scored exactly as before. The
   must-have flag is the other lever: it caps the recommendation, this one only
   shapes the score. */
const CORE_KEYS = new Set(['position', 'experienceyears', 'skills', 'careerlevel']);
const CORE_FLOOR_NUM = 13, CORE_FLOOR_DEN = 20; // 13/20 = 65%: just under the role-fit group's 68 of 100 in the table, so the reference rubric is scored plainly and only broader ones are floored
function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }
function txt(v) { return String(v == null ? '' : v).trim(); }
function toArray(v) { if (Array.isArray(v)) return v.filter((x) => txt(x)); const s = txt(v); return s ? [s] : []; }
function getAssessment(item) { const j = item.json || {}; if (j.output && typeof j.output === 'object') return j.output; if (j.criteria || j.integrity_concerns) return j; const raw = j.text || j.response || j.data || ''; const m = String(raw).match(/\{[\s\S]*\}/); if (m) { try { return JSON.parse(m[0]); } catch (e) {} } return {}; }
/** المفتاح مدفون في المعرّف: `preset__position__d660d64d` → `position`. */
/* ADJACENCY MUST NOT BE PAID TWICE (2026-09-16, measured on the live rubric).
   The assessor counts an ADJACENT role at half value, then the credit is read
   against the band midpoint -- six months for "0-1". So twelve months of any
   adjacent admin job cleared the bar and bought the FULL 25, the heaviest
   criterion in the table. Campaign HR Assistant 2026-09-16, execution 1873: a
   data-entry clerk with `position: partial` and 12 relevant-equivalent months
   scored 83/Hire for an HR role he has never held.

   The same adjacency was being read twice and in opposite directions: it DEBITS
   `position` (partial, 0.5) and CREDITS `experienceYears` (full, 1.0). Relevant
   experience can no longer be worth more than the role match it rests on -- the
   experience fraction is capped at the position fraction.

   SCOPE: the cap applies ONLY on the months path, i.e. only to a band whose
   minimum is 0. A band with a real minimum ("2-3") still discriminates on its
   own, and capping there would punish the honest near-miss this rubric is meant
   to admit -- an HR Officer applying for HR Assistant reads as `position:
   partial` while holding squarely relevant months. On a 0-minimum band the
   employer is not asking for experience at all, so trimming a windfall there
   costs that candidate little and costs the pretender the 25 points he had not
   earned.

   Only `partial` caps. `missing` is deliberately left to the ROLE GATE below,
   which already caps the recommendation and routes the file to a human; capping
   here as well would punish the same fact twice, which is the very defect this
   fixes. `met` gives a cap of 1, i.e. no cap at all. */
function criterionKeyOf(id) {
  return norm(String(id).split('__')[1] || '');
}
function roleFitCapFor(a) {
  const items = Array.isArray(a && a.criteria) ? a.criteria : [];
  for (const c of items) {
    const id = txt(c && (c.criterionId != null ? c.criterionId : c.id));
    if (criterionKeyOf(id) !== 'position') continue;
    return norm(c && c.status) === 'partial' ? STATUS_FRACTION.partial : 1;
  }
  return 1;
}
function weightForId(id, key) {
  const k = norm(key) || norm(String(id).split('__')[1] || '');
  return Object.prototype.hasOwnProperty.call(CRITERION_WEIGHT, k) ? CRITERION_WEIGHT[k] : DEFAULT_WEIGHT;
}
/* An experience band whose minimum is 0 ("0-1") says the employer does not
   require experience. Then "met" is unfalsifiable: every applicant with zero
   relevant months satisfies "minimum 0" and takes the full 25, so the heaviest
   criterion in the table stops discriminating. Seen on campaign HR Assistant
   2026-09-16: a medical student with 0 HR months reached 71 -> Hire because 25
   of his 57 points came from here, while the one candidate with 27 real months
   sat at Consider. A criterion the employer does not require must not carry a
   quarter of the score - it is left out of the denominator, exactly as the
   role-plumbing keys in SKIP are. */
/* Months-based credit for a 0-minimum band (2026-09-16, option b). The band
   "0-1" says experience is welcome but not required; scoring it by status paid
   the full 25 for zero months. Now, when the assessor reports the full-value
   months it decided the status on, credit = min(1, months / band midpoint):
   "0-1" has a 6-month midpoint, so 0 months earns 0, 3 months half, 6+ full.
   Bands with a real minimum keep status scoring - meeting the minimum IS full
   credit there. When "months" is absent the (a) rule still applies: the
   criterion leaves the denominator rather than being paid for nothing. */
function bandMidpointMonths(expectation) {
  const s = norm(expectation).replace(/[–—]/g, '-');
  const nums = (s.match(/[0-9]+/g) || []).map(Number);
  if (nums.length >= 2) return Math.max(1, ((nums[0] + nums[1]) / 2) * 12);
  if (nums.length === 1) return Math.max(6, nums[0] * 12);
  return 6;
}
function monthsFor(a, id) {
  const items = Array.isArray(a && a.criteria) ? a.criteria : [];
  for (const c of items) {
    const cid = txt(c && (c.criterionId != null ? c.criterionId : c.id));
    if (cid !== id) continue;
    if (c.months === null || c.months === undefined || c.months === '') return null;
    const n = Number(c.months);
    return Number.isFinite(n) && n >= 0 ? n : null;
  }
  return null;
}
const experienceBands = new Map();
function expectationMinimumIsZero(expectation) {
  const s = norm(expectation).replace(/[–—]/g, '-');
  const m = s.match(/^([0-9]+)/);
  return Boolean(m) && Number(m[1]) === 0;
}
/** يعيد Map من معرّف المعيار إلى وزنه. */
function getRubricWeights(item, a) {
  const SKIP = new Set(['rolekey', 'labelkey', 'rolematchsource', 'evaluationlanguage']);
  let arr = [];
  try {
    let c = $('Webhook').first().json.body.evaluationRubric;
    if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) { c = []; } }
    if (Array.isArray(c)) arr = c;
  } catch (e) {}
  const map = new Map();
  experienceBands.clear();
  for (const c of arr) {
    const id = txt(c && c.id);
    const key = norm(c && c.key);
    if (!id || SKIP.has(key)) continue;
    if (key === 'experienceyears' && expectationMinimumIsZero(c && c.expectation)) {
